  magitechschild:{ name:'Magitech-Schild', slot:'offhand', block:0.40, armor:3, weight:1, rarity:'epic', value:760, magitech:true, energy:6, mtier:2, guardMul:0.25, sdesc:'Energiefeld: mit Energie hält es jeden Hieb ganz ab (6 Energie je Block, keine Ausdauer), leer wie ein Holzschild. Energiezelle füllt auf.' },

