  grabschaender:{ name: 'Der Grabschänder Egbert', base: 'ghoul', crew: 'skeleton', where: ['ghoul', 'skeleton'], hp: 1.8, dmg: 1.35, power: 'rally', drop: 'grabraeuber', look: { hooded: 1, hood: '#2a2620', apron: 1, apronCol: '#4a3a2a' }, say: 'gräbt die Toten aus und verkauft sie. Die Toten haben ihn dafür nicht vergessen.' },
  totenglocke: { name: 'Die Totenglocke', base: 'skeleton', crew: 'ghoul', where: ['skeleton', 'ghoul'], hp: 2.0, dmg: 1.2, power: 'shock', drop: 'totenglocke', look: { hood: '#2a1a1a', cloak: '#1a1012', glow: '#c05a3a', mark: 'chevron', markCol: '#c05a3a' }, say: 'läutet eine rostige Glocke, und jeder, der sie hört, erstarrt vor Angst.' },
  aschenkoenigin:{ name: 'Aschenkönigin Sabeth', base: 'skeleton', crew: 'skeleton', where: ['skeleton'], hp: 2.1, dmg: 1.35, power: 'burn', drop: 'kriegssense', look: { hooded: 0, helm: 'great', helmCol: '#2a1410', crest: '#ff7a2a', cloak: '#1a0e0c', glow: '#ff7a2a' }, say: 'brannte mit ihrer Stadt und kam als Asche wieder. Ihre Sense glüht noch.' },
  graumaehne:  { name: 'Graumähne', base: 'wolf', crew: 'wolf', where: ['wolf'], hp: 2.4, dmg: 1.3, spd: 1.15, power: 'summon', drop: 'pelt', pal: { body: '#a09a90', dark: '#6a6660' }, say: 'ist ein Wolf so groß wie ein Kalb. Sein Rudel folgt ihm, wohin er auch geht.' },
  schwarzfell: { name: 'Schwarzfell', base: 'wolf', crew: 'wolf', where: ['wolf'], hp: 2.0, dmg: 1.4, spd: 1.25, power: 'charge', drop: 'pelt', pal: { body: '#1e1c1a', dark: '#0e0d0c' }, say: 'jagt nur bei Nacht und hat schon zwei Hirten geholt. Seine Augen leuchten gelb im Dunkeln.' },
  eisenhauer:  { name: 'Eisenhauer', base: 'boar', crew: 'boar', where: ['wolf', 'bandit', 'goblin'], hp: 2.6, dmg: 1.3, armor: 3, power: 'charge', drop: 'pelt', pal: { body: '#2a2420', dark: '#141210' }, say: 'ist ein Keiler, an dessen Schwarte Pfeile abprallen. Er hat die halbe Ernte umgepflügt.' },
  hoehlenbaer: { name: 'Der Alte vom Berg', base: 'bear', crew: 'wolf', where: ['wolf', 'goblin_warrior'], regions: ['mountain', 'eisen'], hp: 2.2, dmg: 1.3, power: 'regen', drop: 'pelt', pal: { body: '#5a3a24', dark: '#2a1a10' }, say: 'ist ein Bär mit weißer Schnauze. Die Jäger sagen, er stirbt nicht.' },
  albinowolf:  { name: 'Der Weiße Hund', base: 'wolf', crew: 'wolf', where: ['wolf'], hp: 2.1, dmg: 1.35, power: 'frost', drop: 'pelt', pal: { body: '#e0dcd0', dark: '#a8a49a', eye: '#c84a4a' }, say: 'ist weiß wie Schnee und kommt mit dem Frost. Wen er beißt, dem gefriert das Blut.' },
  kettenbrecher:{ name: 'Brakk Kettenbrecher', base: 'chain_brute', crew: 'bandit', where: ['bandit', 'goblin_warrior'], regions: ['eisen', 'mountain'], hp: 1.8, dmg: 1.25, armor: 2, power: 'tough', drop: 'warhammer', look: { tabard: '#141210', helmCol: '#3a3634' }, say: 'war Aufseher der Kette und hat sich selbstständig gemacht. Jetzt verkauft er Leute auf eigene Rechnung.' },
  sklaventreiber:{ name: 'Veit mit der Peitsche', base: 'chain_brute', crew: 'bandit', where: ['bandit', 'goblin', 'goblin_warrior'], regions: ['eisen', 'mountain'], hp: 1.7, dmg: 1.3, power: 'shock', drop: 'chain_whip', look: { tabard: '#2a0e10', crest: '#6a1e18' }, say: 'fängt Leute auf den Feldern und treibt sie in die Minen. Seine Peitsche knallt wie ein Blitz.' },
  aschepriester:{ name: 'Aschepriester Morn', base: 'cultist', crew: 'skeleton', where: ['skeleton', 'ghoul', 'bandit'], regions: ['deadland', 'blight'], hp: 1.9, dmg: 1.3, power: 'burn', drop: 'wand', look: { hood: '#3a1a14', robe: '#2a1410', glow: '#ff7a2a' }, say: 'predigt die Asche und opfert Reisende auf seinem Altar. Seine Jünger folgen ihm bis in den Tod.' },
  schattenseher:{ name: 'Die Schattenseherin', base: 'cultist', crew: 'cultist', where: ['skeleton', 'bandit'], regions: ['deadland', 'blight'], hp: 1.7, dmg: 1.4, power: 'regen', drop: 'wand', look: { hood: '#141018', robe: '#1a1420', glow: '#b88af0' }, say: 'sieht die Zukunft in Schatten. Ihre Wunden verschwinden, bevor man sie sieht.' },
  seeteufel:   { name: 'Kapitän Seeteufel', base: 'sea_raider', crew: 'sea_raider', where: ['bandit', 'bandit_spear'], hp: 1.9, dmg: 1.3, power: 'rally', drop: 'kriegssichel', look: { helm: 'hat', helmCol: '#141414', beard: 1, cloak: '#141c24' }, say: 'kapert die Fischerboote und verschleppt die Fischer. Er hat ein Schiff und nichts zu verlieren.' },
  harpunenhexe:{ name: 'Harpunen-Hella', base: 'sea_harpooner', crew: 'sea_raider', where: ['bandit_spear', 'bandit'], hp: 1.7, dmg: 1.4, power: 'charge', drop: 'spear', look: { helm: 'scarf', helmCol: '#2a4a6a', sash: '#8a2a20' }, say: 'wirft ihre Harpune weiter, als andere schießen. Sie zieht ihre Opfer an Land wie Fische.' },
  messingwolf: { name: 'Das Messingungetüm', base: 'automat', crew: 'bandit', where: ['bandit', 'bandit_spear', 'bandit_archer'], regions: ['aurel'], hp: 2.2, dmg: 1.3, armor: 4, power: 'shock', drop: 'ersatzteile', look: { glow: '#ff4020', ge: '#ff4020', armorCol: '#6a3a2a' }, say: 'ist ein Automat, der seinen Herrn erschlagen hat und nun durch die Felder stampft. Blitze knistern um ihn.' },
